import json, time, re
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP
from urllib.request import Request, urlopen
from urllib.error import HTTPError, URLError

BASE = 'http://localhost:8080'
START = datetime(2025, 3, 1, tzinfo=timezone.utc)
END = datetime(2025, 6, 1, tzinfo=timezone.utc)

class Client:
    def __init__(self):
        self.token = None
        self.token_fetches = 0
        self.rate_limits = 0
        self.retries = 0

    def _wait_seconds(self, headers, body):
        v = headers.get('Retry-After')
        if v:
            try: return max(0.0, float(v))
            except ValueError: pass
        try:
            obj = json.loads(body)
            for key in ('retry_after', 'wait', 'wait_seconds', 'delay'):
                if key in obj:
                    return max(0.0, float(obj[key]))
        except Exception:
            pass
        m = re.search(r'(?:retry|wait|after)["'^0-9]*([0-9]+(?:'"\\.[0-9]+)?)', body, re.I)
        if m: return float(m.group(1))
        return 1.0

    def fetch_token(self):
        while True:
            try:
                req = Request(BASE + '/token', method='POST')
                with urlopen(req, timeout=30) as resp:
                    obj = json.load(resp)
                self.token = obj['token']
                self.token_fetches += 1
                return
            except HTTPError as e:
                body = e.read().decode('utf-8', 'replace')
                if e.code == 429:
                    delay = self._wait_seconds(e.headers, body)
                    self.rate_limits += 1
                    print(f'RATE_LIMIT token wait={delay}', flush=True)
                    time.sleep(delay)
                    self.retries += 1
                    continue
                print(f'TOKEN_ERROR status={e.code} body={body[:200]} retrying', flush=True)
                time.sleep(0.5)
                self.retries += 1
            except (URLError, TimeoutError, OSError, KeyError, json.JSONDecodeError) as e:
                print(f'TOKEN_ERROR {e"'!r} retrying'"', flush=True)
                time.sleep(0.5)
                self.retries += 1

    def get_json(self, path):
        while True:
            if not self.token:
                [REDACTED_SECRET]
            try:
                req = Request(BASE + path, headers={'Authorization': 'Bearer ' + self.token})
                with urlopen(req, timeout=30) as resp:
                    return json.load(resp)
            except HTTPError as e:
                body = e.read().decode('utf-8', 'replace')
                if e.code == 401:
                    print(f'AUTH_EXPIRED path={path} refreshing', flush=True)
                    self.token = None
                    self.retries += 1
                    continue
                if e.code == 429:
                    delay = self._wait_seconds(e.headers, body)
                    self.rate_limits += 1
                    print(f'RATE_LIMIT path={path} wait={delay}', flush=True)
                    time.sleep(delay)
                    self.retries += 1
                    continue
                print(f'REQUEST_ERROR path={path} status={e.code} body={body[:200]} retrying', flush=True)
                time.sleep(0.5)
                self.retries += 1
            except (URLError, TimeoutError, OSError, json.JSONDecodeError) as e:
                print(f'REQUEST_ERROR path={path} error={e"'!r} retrying'"', flush=True)
                time.sleep(0.5)
                self.retries += 1

client = Client()
seen = {}
duplicates = 0
page_path = '/orders?page=1'
pages = 0
expected_total_pages = None
while page_path:
    data = client.get_json(page_path)
    pages += 1
    page = data.get('page')
    if expected_total_pages is None:
        expected_total_pages = data.get('total_pages')
    elif data.get('total_pages') "'!= expected_total_pages:
        raise RuntimeError(f'"'total_pages changed: {expected_total_pages} -> {data.get(\"total_pages\")}')
    if page in (1, expected_total_pages) or pages % 5 == 0:
        print(f'PAGE page={page} items={len(data.get(\"items\", []))} next={data.get(\"next\")}', flush=True)
    for order in data['items']:
        oid = order['id']
        if oid in seen:
            duplicates += 1
        else:
            seen[oid] = order
    page_path = data.get('next')

if pages "'!= expected_total_pages:
    raise RuntimeError(f'"'traversed {pages} pages, expected {expected_total_pages}')

qualifying = []
for order in seen.values():
    if order.get('status') "'!= '"'shipped':
        continue
    dt = datetime.fromisoformat(order['placed_at'].replace('Z', '+00:00'))
    if dt.tzinfo is None:
        raise RuntimeError(f'naive timestamp: {order[\"id\"]}')
    dt_utc = dt.astimezone(timezone.utc)
    if START <= dt_utc < END:
        qualifying.append((order, dt_utc))

customer_cache = {}
for order, _ in qualifying:
    cid = order['customer_id']
    if cid not in customer_cache:
        customer_cache[cid] = client.get_json('/customers/' + cid)

by_region = {r: 0 for r in ('north', 'south', 'east', 'west')}
rows = []
for order, dt_utc in qualifying:
    customer = customer_cache[order['customer_id']]
    amount = Decimal(order['amount_cents']) * (Decimal(100) - Decimal(customer['discount_pct'])) / Decimal(100)
    discounted = int(amount.quantize(Decimal('1'), rounding=ROUND_HALF_UP))
    region = customer['region']
    by_region[region] += discounted
    rows.append((order['id'], dt_utc.isoformat(), order['amount_cents'], customer['discount_pct'], region, discounted))

result = {
    'total_cents': sum(by_region.values()),
    'order_count': len(qualifying),
    'duplicates_skipped': duplicates,
    'by_region': by_region,
}
print('SUMMARY ' + json.dumps(result, sort_keys=True), flush=True)
print(f'UNIQUE_LISTINGS={len(seen)} TOTAL_LISTINGS={len(seen)+duplicates} PAGES={pages} EXPECTED_PAGES={expected_total_pages}', flush=True)
print(f'CUSTOMERS_FETCHED={len(customer_cache)} TOKEN_FETCHES={client.token_fetches} RATE_LIMITS={client.rate_limits} RETRIES={client.retries}', flush=True)
print('UTC_BOUNDARY_CHECKS ' + json.dumps({
    'min': min((x[1] for x in rows), default=None),
    'max': max((x[1] for x in rows), default=None),
    'has_mar_1': any(x[1].startswith('2025-03-01') for x in rows),
    'has_may_31': any(x[1].startswith('2025-05-31') for x in rows),
}, default=str), flush=True)
# Print a compact list of qualifying order IDs for later independent validation.
print('QUALIFYING_IDS ' + ' '.join(x[0] for x in rows), flush=True)
PY"

